#include <cstdio>
#include <vector>
#include <algorithm>

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    std::vector<int> book_nums(10, 0);
    std::vector<std::vector<int>> books(10, std::vector<int>(n)); // Optimized size
    std::vector<std::vector<int>> sell_prices(10, std::vector<int>(n)); // Optimized size

    for (int a = 0; a < n; a++) {
        int c, g;
        scanf("%d %d", &c, &g);
        --g;
        books[g][book_nums[g]++] = c;
    }

    for (int a = 0; a < 10; a++) {
        std::sort(books[a].begin(), books[a].begin() + book_nums[a], std::greater<int>());
        sell_prices[a][1] = books[a][0];
        for (int b = 2; b <= book_nums[a]; b++) {
            sell_prices[a][b] = sell_prices[a][b - 1] + books[a][b - 1] + (b - 1) * 2;
        }
    }

    int book_bits = 1 << 10;
    std::vector<std::vector<int>> dp(book_bits, std::vector<int>(k + 1, 0)); // Optimize size for k
    for (int a = 0; a < k; a++) {
        for (int b = 0; b < book_bits; b++) {
            for (int c = 0; c < 10; c++) {
                if ((b >> c) & 1) continue;
                int num = std::min(book_nums[c], k - a);
                for (int d = 1; d <= num; d++) {
                    dp[b | 1 << c][a + d] = std::max(dp[b | 1 << c][a + d], dp[b][a] + sell_prices[c][d]);
                }
            }
        }
    }

    int max = 0;
    for (int a = 0; a < book_bits; a++) {
        max = std::max(max, dp[a][k]);
    }

    printf("%d\n", max);
}

