#include <algorithm>

int dp[1 << 10][2001];
int books[10][2001];
int book_nums[10];
int sell_prices[10][2001];

int greater_int(const void *a, const void *b) {
    return *(int*)b - *(int*)a;
}

int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    for (int a = 0; a < n; a++) {
        int c, g;
        scanf("%d %d", &c, &g);
        --g;
