        }
    }

    int book_bits = 1 << 10;
    for (int a = 0; a < k; a++) {
        for (int b = 0; b < book_bits; b++) {
            for (int c = 0; c < 10; c++) {
                if ((b >> c) & 1) continue;
                int num = std::min(book_nums[c], k - a);
